def count_nums(arr):
    def sum_signed_digits(n):
        if n >= 0:
            return sum(int(d) for d in str(n))
        else:
            s = abs(n)
            sign_digit = -int(str(s)[0])
            rest_sum = sum(int(d) for d in str(s)[1:])
            return sign_digit + rest_sum

    count = 0
